; ============================================== sub packRows ====

packRows:
; ---- flowRowCount = 0
        mov     word [flowRowCount], 0
; ---- n = count
        mov     ax, [packRows__count]
        mov     [packRows__n], ax
; ---- if ( n > maxFlowItems ) {
        cmp     ax, 16
