        test    ax, ax
        jne     .L621                       ; unsigned ==
        ret
.L621:
; ---- flowRow[ 0 ].first = 0
        mov     word [flowRow__first], 0
; ---- flowRow[ 0 ].count = 0
        mov     word [flowRow__count], 0
; ---- flowRowCount = 1
        mov     word [flowRowCount], 1
; ---- used = 0
        mov     word [packRows__used], 0
; ---- for ( u16 i = 0; i < n; i++ ) {
        mov     word [packRows__i], 0
.L624:
        mov     ax, [packRows__i]
        mov     bx, [packRows__n]
        cmp     ax, bx
        jb      .L627                       ; unsigned <
        jmp     .L626
.L627:
; ---- if ( flowRow[ flowRowCount - 1 ].count == 0 ) {
        mov     ax, [flowRowCount]
        dec     ax
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [flowRow__count + bx]
        test    ax, ax
        jne     .L628                       ; unsigned ==
; ---- extra = flowW[i]
        mov     ax, [packRows__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [flowW + bx]
        mov     [packRows__extra], ax
        jmp     .L629
.L628:
; ---- extra = gap + flowW[i]
        mov     ax, [packRows__gap]
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [packRows__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [flowW + bx]
        mov     bx, ax
        pop     ax
        add     ax, bx
        mov     [packRows__extra], ax
.L629:
; ---- if ( flowRow[ flowRowCount - 1 ].count > 0 && used + extra > width ) {
        mov     ax, [flowRowCount]
        dec     ax
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [flowRow__count + bx]
        test    ax, ax
        ja      .L633                       ; unsigned >
        jmp     .L631
.L633:
        mov     ax, [packRows__used]
