        add     ax, bx
        mov     bx, [packRows__width]
        cmp     ax, bx
        jbe     .L631                       ; unsigned >
; ---- if ( flowRowCount >= maxFlowRows ) {
        mov     ax, [flowRowCount]
        cmp     ax, 8
