; ---- flowOverflowed = true
        mov     byte [flowOverflowed], 1
; ---- return
        ret
.L635:
; ---- flowRow[ flowRowCount ].first = i
        mov     ax, [packRows__i]
        mov     bx, [flowRowCount]
        shl     bx, 1                       ; word elements
        mov     [flowRow__first + bx], ax
; ---- flowRow[ flowRowCount ].count = 1
        mov     ax, [flowRowCount]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     word [flowRow__count + bx], 1
; ---- flowRowCount++
        inc     word [flowRowCount]
; ---- used = flowW[i]
        mov     ax, [packRows__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [flowW + bx]
        mov     [packRows__used], ax
        jmp     .L632
.L631:
; ---- flowRow[ flowRowCount - 1 ].count++
        mov     ax, [flowRowCount]
        dec     ax
        shl     ax, 1                       ; word elements
        mov     bx, ax
        inc     word [flowRow__count + bx]
; ---- used += extra
        mov     ax, [packRows__used]
        mov     bx, [packRows__extra]
        add     ax, bx
        mov     [packRows__used], ax
