; ============================================== bool mode__isTextMode ====

mode__isTextMode:
; ---- local bool isTextMode( u8 m ) => m <= 0x03 || m == 0x07
        mov     al, [mode__isTextMode__m]
        cmp     al, 3                       ; byte operands, no widening
        jbe     .L659                       ; unsigned <=
        mov     al, [mode__isTextMode__m]
        cmp     al, 7                       ; byte operands, no widening
        jne     .L657                       ; unsigned ==
.L659:
        mov     ax, 1
        jmp     .L658
.L657:
        xor     ax, ax
.L658:
        mov     [mode__isTextMode__ret], al ; narrowed to bool
        ret

; ============================================== sub saveMode ====

saveMode:
; ---- _ah = 0x0F
        mov     byte [_ah], 15
; ---- int 0x10
        call    int10
; ---- savedMode = _al & 0x7F
        mov     al, [_al]
        xor     ah, ah                      ; u8 -> u16
        and     ax, 127
        mov     [mode__savedMode], al       ; narrowed to u8
; ---- savedRows = u16( bdaRows[0] ) + 1
        mov     dx, 0x40                    ; segment of mode__bdaRows
        mov     es, dx
        mov     al, [es:132]
        xor     ah, ah                      ; u8 -> u16
        inc     ax
        mov     [mode__savedRows], ax
        ret

; ============================================== sub restoreMode ====

restoreMode:
; ---- _ah = 0x00
        mov     byte [_ah], 0
; ---- _al = savedMode
        mov     al, [mode__savedMode]
        mov     [_al], al                   ; u8 -> u8, no widening
; ---- int 0x10
        call    int10
; ---- if ( isTextMode( savedMode ) && savedRows > 25 ) {
        mov     al, [mode__savedMode]
        mov     [mode__isTextMode__m], al   ; u8 -> u8, no widening
        call    mode__isTextMode
        mov     al, [mode__isTextMode__ret]
        xor     ah, ah                      ; bool -> u16
        test    ax, ax
        jz      .L662
        mov     ax, [mode__savedRows]
        cmp     ax, 25
        jbe     .L662                       ; unsigned >
; ---- _ax = 0x1112
        mov     word [_ax], 4370
; ---- _bl = 0
        mov     byte [_bl], 0
; ---- int 0x10
        call    int10
.L662:
; ---- curW = 0
        mov     word [mode__curW], 0
; ---- curH = 0
        mov     word [mode__curH], 0
; ---- curElems = 0
        mov     word [mode__curElems], 0
; ---- curSeg = 0
        mov     word [mode__curSeg], 0
; ---- curElemBytes = 0
        mov     byte [mode__curElemBytes], 0
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int10:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x10
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int16:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x16
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

